#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void maxpool1d_kernel(
    const half* input,
    half* output,
    int* indices,
    int batch_size,
    int num_features,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool return_indices
) {
    int batch_idx = blockIdx.x;
    int feature_idx = blockIdx.y;
    int output_pos = threadIdx.x;

    if (batch_idx >= batch_size || feature_idx >= num_features || output_pos >= output_length) {
        return;
    }

    int input_start = output_pos * stride - padding;
    half max_val = -65504.0h; // Minimum value for fp16
    int max_idx = -1;

    for (int k = 0; k < kernel_size; ++k) {
        int input_idx = input_start + k * dilation;

        if (input_idx >= 0 && input_idx < input_length) {
            half val = input[batch_idx * (num_features * input_length) + 
                           feature_idx * input_length + 
                           input_idx];

            if (val > max_val) {
                max_val = val;
                max_idx = input_idx;
            }
        }
    }

    int output_idx = batch_idx * (num_features * output_length) + 
                     feature_idx * output_length + 
                     output_pos;

    output[output_idx] = max_val;

    if (return_indices) {
        indices[output_idx] = max_idx;
    }
}

torch::Tensor maxpool1d_forward(
    const torch::Tensor& input,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool return_indices
) {
    TORCH_CHECK(input.dtype() == torch::kFloat16, "Input must be float16");
    TORCH_CHECK(input.dim() == 3, "Input must be 3-dimensional (batch, features, sequence)");

    auto batch_size = input.size(0);
    auto num_features = input.size(1);
    auto input_length = input.size(2);

    int output_length = (input_length + 2 * padding - (dilation * (kernel_size - 1) + 1)) / stride + 1;

    auto options = torch::TensorOptions().dtype(torch::kFloat16).device(torch::kCUDA);
    auto output = torch::zeros({batch_size, num_features, output_length}, options);

    torch::Tensor indices = torch::zeros({batch_size, num_features, output_length}, torch::TensorOptions().dtype(torch::kInt32).device(torch::kCUDA));

    if (output_length <= 0) {
        return output;
    }

    dim3 grid(batch_size, num_features);
    dim3 block(output_length);

    maxpool1d_kernel<<<grid, block>>>(
        input.data_ptr<half>(),
        output.data_ptr<half>(),
        indices.data_ptr<int>(),
        batch_size,
        num_features,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding,
        dilation,
        return_indices
    );

    cudaDeviceSynchronize();

    if (return_indices) {
        return torch::cat({output, indices.to(torch::kFloat16)}, 1);
    }

    return output;
}
